#!/usr/bin/env bash
set -euo pipefail

# F-2 web-session concurrent composition: the extracted start, grant, token and
# delete drivers plus the extracted device-revocation driver over one shared
# world (rows, web_token take store, the per-session token claim, lockout
# sentinel, SQL rows, devices and accounts).
#
# This script does NOT regenerate the four web-session drivers. It reuses
# `proofs/fstar/extraction-websession-driver/` (regenerated by
# verify-fstar-websession-driver.sh, which runs first) and regenerates only the
# revocation driver it needs into a private directory, so a parallel
# revocation job cannot delete the include directory mid-run.

proof_root=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
cd "$proof_root"

for command_name in cargo cargo-hax driver-hax-frontend-exporter hax-engine fstar.exe z3-4.13.3 jq python3; do
  command -v "$command_name" >/dev/null || {
    echo "$command_name is missing; follow README.md" >&2
    exit 1
  }
done

version=$(fstar.exe --version)
printf '%s\n' "$version"
[[ ${version%%$'\n'*} == 'F* 2025.10.06' ]] || {
  echo 'unexpected F* version' >&2
  exit 2
}

websession_gen=proofs/fstar/extraction-websession-driver
revocation_gen=proofs/fstar/extraction-websession-revocation
composition_dir=proofs/fstar/websession-composition
composition=$composition_dir/Vela_session_policy_websession_composition.fst

for f in \
  "$websession_gen/Vela_session_policy.Challenge.fst" \
  "$websession_gen/Vela_session_policy.fst" \
  "$websession_gen/Vela_session_policy.Websession_driver.fst" \
  "$composition"; do
  [[ -f $f ]] || {
    echo "missing $f (run verify-fstar-websession-driver.sh first)" >&2
    exit 1
  }
done

# The composition also runs the extracted device-revocation driver (its
# cascade ends the sessions the device approved, U-18). Extract only that
# driver, into a private directory.
rm -rf "$revocation_gen"
cargo hax into \
  --output-dir "$revocation_gen" \
  -i '-** +vela_session_policy::revocation_driver::begin_revocation +vela_session_policy::revocation_driver::step' \
  fstar --z3rlimit 500

mapfile -t generated < <(
  find "$websession_gen" "$revocation_gen" -maxdepth 1 -type f -name '*.fst' -print | sort
)
if (( ${#generated[@]} == 0 )); then
  echo 'no generated web-session/revocation modules' >&2
  exit 1
fi

python3 "$proof_root/../../security/formal/check-driver-proof-sources.py" \
  --generated "${generated[@]}" \
  --proof "$composition" \
  --include-dir "$proof_root/$websession_gen" \
  --include-dir "$proof_root/$revocation_gen" \
  --include-dir "$proof_root/$composition_dir"

hax_lib_root=$(
  cargo metadata --format-version 1 |
    jq -r '.packages[] | select(.name == "hax-lib") | .manifest_path | sub("/Cargo.toml$"; "")'
)
[[ -n $hax_lib_root && -d $hax_lib_root ]] || {
  echo 'could not locate hax-lib proof libraries' >&2
  exit 1
}

fstar_args=(
  --cmi
  --cache_off
  --warn_error -331
  --z3rlimit 16000
  --z3version 4.13.3
  --already_cached '+Prims+FStar+LowStar+C+Spec.Loops+TestLib'
  --include "$hax_lib_root/proof-libs/fstar/core"
  --include "$hax_lib_root/proof-libs/fstar/rust_primitives"
  --include "$hax_lib_root/proofs/fstar/extraction"
  --include "$websession_gen"
  --include "$revocation_gen"
  --include "$composition_dir"
  "${generated[@]}" "$composition"
)
printf 'F* web-session-composition argv:'
printf ' %q' "${fstar_args[@]}"
printf '\n'
fstar.exe "${fstar_args[@]}"

echo "web-session composition: for every schedule at most one token per session, no token after the session's delete or approver-cascade revocation, grants only from the owning active approver and only for pending rows, start inserts only a pending row, no cross-account delete"
sha256sum "${generated[@]}" "$composition" src/websession_driver.rs
